"""Patch the platform files generated by `flutter create` (run in CI)."""
import re
from pathlib import Path

m = Path("android/app/src/main/AndroidManifest.xml")
s = m.read_text(encoding="utf-8")
perms = [
    "android.permission.INTERNET",
    "android.permission.ACCESS_COARSE_LOCATION",
    "android.permission.ACCESS_FINE_LOCATION",
    "android.permission.REQUEST_INSTALL_PACKAGES",
    "android.permission.POST_NOTIFICATIONS",
    "android.permission.RECEIVE_BOOT_COMPLETED",
]
for p in perms:
    if p not in s:
        s = s.replace("<application", f'<uses-permission android:name="{p}"/>\n    <application', 1)
s = re.sub(r'android:label="[^"]*"', 'android:label="מבצעי רמי"', s, count=1)
https_query = '<intent><action android:name="android.intent.action.VIEW"/><data android:scheme="https"/></intent>'
if https_query not in s:
    if "<queries>" in s:
        s = s.replace("<queries>", "<queries>\n        " + https_query, 1)
    else:
        s = s.replace("</manifest>", f"    <queries>{https_query}</queries>\n</manifest>")
# ota_update: FileProvider + install result receiver
ota = """
        <provider
            android:name="sk.fourq.otaupdate.OtaUpdateFileProvider"
            android:authorities="${applicationId}.ota_update_provider"
            android:exported="false"
            android:grantUriPermissions="true">
            <meta-data android:name="android.support.FILE_PROVIDER_PATHS" android:resource="@xml/filepaths" />
        </provider>
        <receiver android:name="sk.fourq.otaupdate.InstallResultReceiver" android:exported="false">
            <intent-filter><action android:name="${applicationId}.ACTION_INSTALL_COMPLETE" /></intent-filter>
        </receiver>
"""
if "OtaUpdateFileProvider" not in s:
    s = s.replace("</application>", ota + "    </application>", 1)
m.write_text(s, encoding="utf-8")
xml = Path("android/app/src/main/res/xml")
xml.mkdir(parents=True, exist_ok=True)
(xml / "filepaths.xml").write_text(
    '<?xml version="1.0" encoding="utf-8"?>\n'
    '<paths xmlns:android="http://schemas.android.com/apk/res/android">\n'
    '    <files-path name="internal_apk_storage" path="ota_update/" />\n'
    '    <external-path name="external_download" path="Download" />\n'
    '</paths>\n',
    encoding="utf-8",
)
print(s)

# Core library desugaring (required by ota_update)
kts = Path("android/app/build.gradle.kts")
groovy = Path("android/app/build.gradle")
if kts.exists():
    g = kts.read_text(encoding="utf-8")
    if "isCoreLibraryDesugaringEnabled" not in g:
        g = g.replace("compileOptions {", "compileOptions {\n        isCoreLibraryDesugaringEnabled = true", 1)
        g += '\ndependencies {\n    coreLibraryDesugaring("com.android.tools:desugar_jdk_libs:2.1.4")\n}\n'
        kts.write_text(g, encoding="utf-8")
elif groovy.exists():
    g = groovy.read_text(encoding="utf-8")
    if "coreLibraryDesugaringEnabled" not in g:
        g = g.replace("compileOptions {", "compileOptions {\n        coreLibraryDesugaringEnabled true", 1)
        g += "\ndependencies {\n    coreLibraryDesugaring 'com.android.tools:desugar_jdk_libs:2.1.4'\n}\n"
        groovy.write_text(g, encoding="utf-8")
print("desugaring patched:", kts.exists() or groovy.exists())

# minSdk 24 (flutter_local_notifications) and the monochrome notification icon
for gp in (kts, groovy):
    if gp.exists():
        g = gp.read_text(encoding="utf-8")
        g = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = 24", g)
        g = re.sub(r"minSdkVersion\s+flutter\.minSdkVersion", "minSdkVersion 24", g)
        gp.write_text(g, encoding="utf-8")
import shutil
drawable = Path("android/app/src/main/res/drawable")
drawable.mkdir(parents=True, exist_ok=True)
shutil.copy("assets/brand/notify.png", drawable / "ic_stat_notify.png")
